(2964, 0, 'form', '{\"required_fields\":\"email\",\"display_fields\":\"phone,email,subject,address\",\"name\":\"Bridgett McNally\",\"email\":\"bridgett.mcnally@outlook.com\",\"address\":\"Corso Porta Nuova 143\",\"phone\":\"3255429423\",\"subject\":\"Create Your Own Music in Just a Few Clicks - Just Point, Click & Create!\",\"content\":\"SoundSparkGenerator is a cloud-based tool that lets you create custom music styles in seconds by mixing genres, instruments, and vocal options. \\r\\n\\r\\nhttps:\\/\\/finsup.site\\/SoundSparkGenerator\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\nto UNSUBSCRIBE:\\r\\nhttps:\\/\\/www.novaai.expert\\/unsubscribe?domain=glimmergowns.com\\r\\nAddress: 108 West Street Comstock Park, MI 48721\"}', 'created', 'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/114.0.0.0 Safari/537.36', '104.207.39.44', 0, 229, 'Bridgett McNally', 'info', '2026-01-19 16:59:28', '2026-01-19 16:59:28'),
