(15, 'Botble\\Page\\Models\\Page', 6, 1, 'template', NULL, 'default', '2024-06-20 09:55:19', '2024-06-20 09:55:19'),
(16, 'Botble\\Page\\Models\\Page', 6, 1, 'description', NULL, 'Find answers to common questions about Trendzap. Explore our FAQs for information on orders, shipping, returns, sizing, and more. We\'re here to help you have the best shopping experience!', '2024-06-20 09:55:19', '2024-06-20 09:55:19'),
(17, 'Botble\\Page\\Models\\Page', 5, 1, 'description', NULL, 'Get in touch with Trendzap! We\'re here to help with any questions or concerns. Reach out to our customer support team via email or phone, and we\'ll respond promptly. Connect with us today!', '2024-06-20 09:55:40', '2024-06-20 09:55:40'),
(18, 'Botble\\Page\\Models\\Page', 4, 1, 'description', '', 'Welcome to the Trendzap Blog! Dive into the latest fashion trends, styling tips, and behind-the-scenes insights. Stay inspired with our curated content, designed to celebrate and empower your unique style.', '2024-06-20 09:56:03', '2024-06-20 09:56:03'),
(19, 'Botble\\Page\\Models\\Page', 3, 1, 'description', NULL, 'Explore exclusive savings with Trendzap\'s Coupons Page! Discover discounts and special offers on your favorite fashion items. Grab your coupon codes and elevate your style at a great price.', '2024-06-20 09:56:29', '2024-06-20 09:56:29'),
(20, 'Botble\\Page\\Models\\Page', 2, 1, 'description', NULL, 'Discover Trendzap\'s diverse Product Categories! Explore our curated collections of women\'s fashion, including clothing, accessories, and more. Find the perfect pieces to elevate your wardrobe.', '2024-06-20 09:56:51', '2024-06-20 09:56:51'),
(21, 'Botble\\Page\\Models\\Page', 1, 1, 'description', '', 'Welcome to Trendzap! Your premier destination for stylish women\'s fashion. Explore our latest collections, find inspiration, and shop with confidence. Redefine your style with Trendzap.', '2024-06-20 09:57:27', '2024-06-20 09:57:27'),
